package practice;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.HashMap;
import java.util.Map;

/** Report texts, fetched from a slow source once and then served from memory. */
public class ReportCache {

    /** Where report texts come from: a file share, an object store. */
    public interface ReportSource {
        String fetch(String name) throws IOException;
    }

    private final ReportSource source;
    private final Map<String, String> texts = new HashMap<>();

    public ReportCache(ReportSource source) {
        this.source = source;
    }

    /**
     * The text of the named report. The first call for a name fetches it from the source;
     * later calls return the cached text. When the source fails, the caller gets what it threw.
     */
    public String get(String name) throws IOException {
        try {
            return texts.computeIfAbsent(name, this::fetchForCache);
        } catch (UncheckedIOException e) {
            throw e.getCause();
        }
    }

    /** The mapping function computeIfAbsent runs for a name that isn't cached yet. */
    String fetchForCache(String name) {
        try {
            return source.fetch(name);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

package practice;

import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            CountingShare share = new CountingShare();
            ReportCache cache = new ReportCache(share);
            System.out.println("first read: " + cache.get("monthly-sales"));
            System.out.println("second read: " + cache.get("monthly-sales"));
            System.out.println("fetches from the share: " + share.fetches);
            try {
                cache.get("old-archive");
            } catch (IOException failed) {
                System.out.println("caller received: " + failed);
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    /** A share that knows every report except the archived one, and counts its fetches. */
    static class CountingShare implements ReportCache.ReportSource {
        int fetches;

        @Override
        public String fetch(String name) throws IOException {
            fetches++;
            if (name.equals("old-archive")) throw new FileNotFoundException("no report " + name);
            return "contents of " + name;
        }
    }
}

